function maxCoins(nums) {
  const vals = [1, ...nums, 1];                  // a 1 at each end: bursting next to a wall
  const memo = new Map();
  const best = (l, r) => {                       // most coins for the balloons strictly between l and r
    if (r - l < 2) return 0;                     // nothing between them
    const key = l * vals.length + r;
    if (memo.has(key)) return memo.get(key);
    let most = 0;
    for (let k = l + 1; k < r; k++) {            // k is the LAST balloon burst between l and r
      most = Math.max(most, best(l, k) + vals[l] * vals[k] * vals[r] + best(k, r));
    }
    memo.set(key, most);
    return most;
  };
  return best(0, vals.length - 1);
}

